(7265207, 1130297, 96751, '<td valign="top">Front page material, if not top 5.  Splendid capture and preservation of detail.</td>', 'Front page material, if not top 5.  Splendid capture and preservation of detail.', '2014-09-22 18:00:32.000000', NULL, 1),
(7265209, 1130294, 96751, '<td valign="top">LOVE this. My artsy favorite of the challenge.</td>', 'LOVE this. My artsy favorite of the challenge.', '2014-09-22 18:01:00.000000', NULL, 1),
